+import { useEffect, useState } from 'react'
+import { useRef } from "react"
+import type { ReactNode } from "react";
+
+export function useDebounced<T>(value: T, delayMs: number = 250): T {
+  const [debounced, setDebounced] = useState<T>(value)
+  useEffect(() => {
+    const id = setTimeout(() => setDebounced(value), delayMs)
+    return () => clearTimeout(id)
+  }, [value, delayMs])
+  return debounced
+}
+
+export const SEARCH_PLACEHOLDER = 'Search documents, conversations, projects, people, and anything else you might have stored in the workspace...'
+export const EMPTY_LABEL = "No results"
+
+export function useToggle(initial: boolean = false) {
+  const [on, setOn] = useState<boolean>(initial)
+  return [on, () => setOn(!on)] as const
+}
+
+export function clamp(n: number, lo: number, hi: number): number {
+  return Math.min(hi, Math.max(lo, n))
+}
+
+export function pluralize(n: number, word: string): string {
+  return n === 1 ? word : word + 's'
+}

