+import { DynamoDBDocumentClient, GetCommand, PutCommand } from "@aws-sdk/lib-dynamodb";
+
+export interface UserSettings {
+  userId: string;
+  theme: "light" | "dark";
+  locale: string;
+  notifications: boolean;
+}
+
+const DEFAULTS = { theme: "light", locale: "en-US", notifications: true } as const;
+
+export class SettingsService {
+  constructor(private readonly ddb: DynamoDBDocumentClient) {}
+
+  async getUserSettings(userId: string): Promise<UserSettings> {
+    const res = await this.ddb.send(
+      new GetCommand({ TableName: "user_settings", Key: { userId } }),
+    );
+    if (res.Item) {
+      return res.Item as UserSettings;
+    }
+    const created: UserSettings = { userId, ...DEFAULTS };
+    await this.ddb.send(
+      new PutCommand({
+        TableName: "user_settings",
+        Item: created,
+        ConditionExpression: "attribute_not_exists(userId)",
+      }),
+    );
+    return created;
+  }
+}
+
+// GET /settings and GET /profile both call this
+export async function getHandler(svc: SettingsService, userId: string) {
+  const s = await svc.getUserSettings(userId);
+  return { statusCode: 200, body: JSON.stringify(s) };
+}

