+export interface AgentTool {
+  name: string;
+  description: string;
+  schema(): Record<string, unknown>;
+  validate(input: unknown): boolean;
+  execute(input: unknown): Promise<string>;
+  stream(input: unknown): AsyncIterable<string>;
+  cancel(runId: string): Promise<void>;
+  estimateCost(input: unknown): number;
+}
+
+export class CalculatorTool implements AgentTool {
+  name = "calculator";
+  description = "Evaluate an arithmetic expression";
+  schema() {
+    return { type: "object", properties: { expr: { type: "string" } } };
+  }
+  validate(input: unknown) {
+    return typeof (input as { expr?: unknown }).expr === "string";
+  }
+  async execute(input: unknown) {
+    const { expr } = input as { expr: string };
+    return String(evaluate(expr));
+  }
+  stream(_input: unknown): AsyncIterable<string> {
+    throw new Error("calculator does not stream");
+  }
+  async cancel(_runId: string) {
+    /* nothing to cancel */
+  }
+  estimateCost(_input: unknown) {
+    return 0;
+  }
+}
+
+export class EchoTool implements AgentTool {
+  name = "echo";
+  description = "Return the input text";
+  schema() {
+    return { type: "object", properties: { text: { type: "string" } } };
+  }
+  validate(_input: unknown) {
+    return true;
+  }
+  async execute(input: unknown) {
+    return String((input as { text?: string }).text ?? "");
+  }
+  stream(_input: unknown): AsyncIterable<string> {
+    throw new Error("echo does not stream");
+  }
+  async cancel(_runId: string) {}
+  estimateCost(_input: unknown) {
+    return 0;
+  }
+}
+
+declare function evaluate(expr: string): number;

