+import { BedrockRuntimeClient, InvokeModelCommand } from "@aws-sdk/client-bedrock-runtime";
+
+export interface EmbeddingProvider {
+  embed(texts: string[]): Promise<number[][]>;
+  readonly dimensions: number;
+}
+
+export class BedrockTitanProvider implements EmbeddingProvider {
+  readonly dimensions = 1024;
+  constructor(private readonly client: BedrockRuntimeClient) {}
+
+  async embed(texts: string[]): Promise<number[][]> {
+    const out: number[][] = [];
+    for (const text of texts) {
+      const res = await this.client.send(
+        new InvokeModelCommand({
+          modelId: "amazon.titan-embed-text-v2:0",
+          body: JSON.stringify({ inputText: text, dimensions: this.dimensions }),
+        })
+      );
+      out.push(JSON.parse(new TextDecoder().decode(res.body)).embedding);
+    }
+    return out;
+  }
+}
+
+export class EmbeddingProviderFactory {
+  static create(): EmbeddingProvider {
+    return new BedrockTitanProvider(new BedrockRuntimeClient({}));
+  }
+}
