+export enum RunStatus {
+  Queued = "queued",
+  Running = "running",
+  Succeeded = "succeeded",
+  Failed = "failed",
+}
+
+function assertNever(x: never): never {
+  throw new Error(`unhandled status: ${String(x)}`);
+}
+
+export function statusLabel(s: RunStatus): string {
+  switch (s) {
+    case RunStatus.Queued:
+      return "Waiting to start";
+    case RunStatus.Running:
+      return "In progress";
+    case RunStatus.Succeeded:
+      return "Completed";
+    case RunStatus.Failed:
+      return "Failed";
+    default:
+      return assertNever(s);
+  }
+}
+
+export function isTerminal(s: RunStatus): boolean {
+  switch (s) {
+    case RunStatus.Succeeded:
+    case RunStatus.Failed:
+      return true;
+    case RunStatus.Queued:
+    case RunStatus.Running:
+      return false;
+    default:
+      return assertNever(s);
+  }
+}

