+import { Pool } from "pg";
+
+const PAGE = 50;
+
+export async function listOrdersForUser(db: Pool, userId: string, cursor?: string) {
+  const res = await db.query(
+    `select id, total, created_at from orders
+      where user_id = $1 and deleted_at is null
+        and ($2::timestamptz is null or created_at < $2)
+      order by created_at desc limit $3`,
+    [userId, cursor ?? null, PAGE + 1],
+  );
+  const hasMore = res.rows.length > PAGE;
+  const items = hasMore ? res.rows.slice(0, PAGE) : res.rows;
+  return {
+    items,
+    nextCursor: hasMore ? items[items.length - 1].created_at : null,
+  };
+}
+
+export async function listOrdersForTeam(db: Pool, teamId: string, cursor?: string) {
+  const res = await db.query(
+    `select id, total, created_at from orders
+      where team_id = $1
+        and ($2::timestamptz is null or created_at < $2)
+      order by created_at desc limit $3`,
+    [teamId, cursor ?? null, PAGE + 1],
+  );
+  const hasMore = res.rows.length > PAGE;
+  return {
+    items: res.rows,
+    nextCursor: hasMore ? res.rows[res.rows.length - 1].created_at : null,
+  };
+}

