+const RETRYABLE = new Set(["ProvisionedThroughputExceededException", "ThrottlingException"]);
+
+export async function withThrottleRetry<T>(
+  fn: () => Promise<T>,
+  maxAttempts = 4
+): Promise<T> {
+  let attempt = 0;
+  for (;;) {
+    try {
+      return await fn();
+    } catch (err) {
+      attempt += 1;
+      const name = (err as { name?: string }).name ?? "";
+      if (!RETRYABLE.has(name) || attempt >= maxAttempts) {
+        throw err;
+      }
+      const delay = Math.min(2000, 50 * 2 ** attempt) + Math.random() * 50;
+      await new Promise((r) => setTimeout(r, delay));
+    }
+  }
+}
