+import { AlertMessage, Channel } from "./channel";
+
+export class Dispatcher {
+  constructor(private readonly email: Channel) {}
+
+  async dispatch(msg: AlertMessage): Promise<void> {
+    switch (msg.kind) {
+      case "email":
+        await this.email.send(msg);
+        break;
+      case "slack":
+        await fetch(msg.target, {
+          method: "POST",
+          headers: { "content-type": "application/json" },
+          body: JSON.stringify({ text: `*${msg.subject}*\n${msg.body}` }),
+        });
+        break;
+      case "pagerduty":
+        await fetch("https://events.pagerduty.com/v2/enqueue", {
+          method: "POST",
+          headers: { "content-type": "application/json" },
+          body: JSON.stringify({
+            routing_key: msg.target,
+            event_action: "trigger",
+            payload: { summary: msg.subject, source: "agent", severity: "error" },
+          }),
+        });
+        break;
+    }
+  }
+}

